"""Export deterministic, independent 2.5D architecture as SVG + transparent PNG."""
from pathlib import Path
import subprocess
root=Path('assets/ark-between-worlds/details');root.mkdir(exist_ok=True)
def export(name,w,h,body):
 defs='''<defs><linearGradient id="stone" x1="0" y1="0" x2=".7" y2="1"><stop stop-color="#fff9ea"/><stop offset=".5" stop-color="#e1dfdd"/><stop offset="1" stop-color="#b1b8c6"/></linearGradient><linearGradient id="top" x2="0" y2="1"><stop stop-color="#fffdf5"/><stop offset="1" stop-color="#dedfe5"/></linearGradient><linearGradient id="side" x2="0" y2="1"><stop stop-color="#a5afc0"/><stop offset="1" stop-color="#707d94"/></linearGradient><linearGradient id="glass" x2="1" y2="1"><stop stop-color="#e3ffff"/><stop offset=".5" stop-color="#85cdd9"/><stop offset="1" stop-color="#3b8099"/></linearGradient></defs>'''
 svg=f'<svg xmlns="http://www.w3.org/2000/svg" width="{w}" height="{h}" viewBox="0 0 {w} {h}">{defs}{body}</svg>'
 (root/(name+'.svg')).write_text(svg)
 # Supersampling keeps bevel highlights clean at the small runtime scale.
 subprocess.run(['magick','-background','none','-density','192',str(root/(name+'.svg')),'-resize',f'{w}x{h}',str(root/(name+'.png'))],check=True)
# Tapered flight: broad lower treads, shaded risers, beveled cheeks and handrails.
parts=['<path d="M8 18L151 18L173 115L0 115Z" fill="#52687c" opacity=".18"/>']
for i in range(6):
 y=12+i*14;l=26-i*3.4;r=144+i*3.4
 parts.append(f'<path d="M{l} {y}H{r}L{r+3.4} {y+9}H{l-3.4}Z" fill="url(#top)" stroke="#abaeb5" stroke-width=".7"/><path d="M{l-3.4} {y+9}H{r+3.4}V{y+14}H{l-3.4}Z" fill="url(#side)"/><path d="M{l-2} {y+9}H{r+2}" stroke="#fffaf0" stroke-width="1.7"/>')
parts+=['<path d="M16 5L27 8L6 104L0 107Z" fill="url(#side)"/><path d="M16 0L31 5L9 102L0 99Z" fill="url(#stone)" stroke="#bbb5a9"/><path d="M143 5L157 0L170 99L159 103Z" fill="url(#stone)" stroke="#9da5b3"/><path d="M157 0L170 99V110L163 108Z" fill="url(#side)"/><path d="M23 7L5 96M150 7L164 96" stroke="#bd9d62" stroke-width="2"/><path d="M25 13L9 91M148 13L159 91" stroke="#a7e2e6" stroke-width="1.3"/><path d="M10 105H160L170 111H0Z" fill="url(#top)" stroke="#aeb7c3"/>']
export('stair-flight',170,118,''.join(parts))
export('ark-lantern',64,114,'''<ellipse cx="32" cy="105" rx="29" ry="8" fill="#4f607b" opacity=".22"/><path d="M7 96L32 84L57 96V104L32 113L7 104Z" fill="url(#side)"/><path d="M7 96L32 84L57 96L32 106Z" fill="url(#stone)" stroke="#b7ae99"/><path d="M22 94V32L32 25L43 32V94L32 99Z" fill="url(#stone)" stroke="#9aa3b3"/><path d="M27 42V88M37 42V88" stroke="#a6dae2" stroke-width="2"/><path d="M14 28L32 15L50 28L32 39Z" fill="#d0bc90" stroke="#95866c"/><path d="M18 27L32 5L46 27L32 35Z" fill="url(#glass)" stroke="#a8d9e4"/><path d="M32 7V33" stroke="#f5ffff" stroke-width="2"/>''')
export('arrival-landing',420,130,'''<ellipse cx="210" cy="102" rx="200" ry="25" fill="#718298" opacity=".14"/><path d="M20 45L125 6H295L400 45V76L295 118H125L20 76Z" fill="url(#side)" stroke="#8993a5"/><path d="M20 45L125 6H295L400 45L295 91H125Z" fill="url(#top)" stroke="#d5c5a4" stroke-width="3"/><path d="M40 45L130 14H290L380 45L290 83H130Z" fill="none" stroke="#aaaeb9"/><path d="M160 39L210 19L260 39L210 60Z" fill="none" stroke="#b6a27d" stroke-width="2"/><path d="M183 40L210 30L237 40M191 49L210 42L229 49" fill="none" stroke="#699cae" stroke-width="2"/><path d="M135 94H285" stroke="#7dbdc9" stroke-width="2"/>''')
export('maintenance-console',100,122,'''<ellipse cx="50" cy="108" rx="46" ry="12" fill="#4e627b" opacity=".2"/><path d="M16 91L50 77L86 91V106L50 119L16 106Z" fill="url(#side)"/><path d="M16 91L50 77L86 91L50 104Z" fill="url(#stone)"/><path d="M36 95V48L52 42L66 49V97L51 102Z" fill="url(#side)"/><path d="M12 30L65 7L89 25L34 50Z" fill="url(#stone)" stroke="#c6bcaa" stroke-width="3"/><path d="M18 30L64 12L81 25L35 44Z" fill="#284357"/><path d="M27 30L62 17M32 35L57 25" stroke="#91d3dc" stroke-width="2"/><path d="M34 50L89 25V33L34 59L12 39V30Z" fill="url(#side)"/><path d="M45 68V87" stroke="#8dc5d3" stroke-width="3"/>''')
export('repair-station',160,138,'''<ellipse cx="80" cy="117" rx="72" ry="16" fill="#536c7e" opacity=".2"/><path d="M14 78L91 46L148 72V112L70 138L14 112Z" fill="url(#side)"/><path d="M14 78L91 46L148 72L70 105Z" fill="url(#stone)" stroke="#bcab8a" stroke-width="2"/><path d="M20 88L64 108V128L20 109Z" fill="#8b9ba8"/><path d="M82 108L137 85V106L82 125Z" fill="#a9b3bc"/><path d="M30 79L89 55L129 73L70 97Z" fill="#8c969e"/><path d="M47 79L83 64L105 74L70 89Z" fill="#d2d6cf"/><path d="M89 47V13L112 5L121 12V51" fill="none" stroke="#a6a9aa" stroke-width="9"/><path d="M120 14L137 31L130 39" fill="none" stroke="#9a8668" stroke-width="6"/><path d="M34 62V29L43 24V66" fill="none" stroke="#bbc8cb" stroke-width="6"/><path d="M31 32L43 28" stroke="#f0d395" stroke-width="5"/><path d="M96 113L122 102" stroke="#e5be6c" stroke-width="2"/>''')
export('docking-cradle',380,180,'''<ellipse cx="190" cy="125" rx="177" ry="48" fill="#405675" opacity=".17"/><ellipse cx="190" cy="105" rx="155" ry="52" fill="none" stroke="#9ba8b9" stroke-width="14"/><ellipse cx="190" cy="101" rx="155" ry="52" fill="none" stroke="#e0dccf" stroke-width="9"/><ellipse cx="190" cy="102" rx="144" ry="46" fill="none" stroke="#9facc4" stroke-width="1.5"/><path d="M30 105V38L48 29L63 37V100M317 100V37L332 29L350 38V105" fill="none" stroke="#8b98ae" stroke-width="12"/><path d="M34 38V96M346 38V96" stroke="#bb9eca" stroke-width="3"/><path d="M48 29L100 6L114 15V53M332 29L280 6L266 15V53" fill="none" stroke="#dad8d1" stroke-width="11"/><path d="M110 15V49M270 15V49" stroke="#cab6d2" stroke-width="3"/><path d="M69 152L117 132M311 152L263 132" stroke="#c4ad7a" stroke-width="4"/>''')
export('support-bracket',100,105,'''<path d="M8 10L44 0L91 22V42L58 56L48 94L29 102V53L8 36Z" fill="url(#side)" stroke="#8290a4"/><path d="M8 10L44 0L91 22L58 36Z" fill="url(#stone)"/><path d="M36 52L58 42L50 83L39 89Z" fill="#b8c1c9"/><path d="M65 31L79 25" stroke="#bbad8f" stroke-width="2"/>''')
export('gateway-rubble',190,100,'''<ellipse cx="94" cy="77" rx="88" ry="18" fill="#556b85" opacity=".15"/><path d="M9 54L40 41L63 55V76L34 88L9 73Z" fill="url(#side)"/><path d="M9 54L40 41L63 55L34 67Z" fill="url(#stone)"/><path d="M95 43L113 11L151 26L146 66L118 80L93 63Z" fill="url(#stone)" stroke="#a7a9b0"/><path d="M113 11L125 35L118 80M125 35L151 26" fill="none" stroke="#807d7a"/><path d="M66 75L86 63L103 74L83 87Z" fill="#c7c8c8"/><path d="M161 76L177 67L185 78L169 84Z" fill="#b4bdc7"/>''')
export('bridge-threshold',200,100,'''<path d="M15 28L100 4L185 28V69L100 97L15 69Z" fill="url(#side)" stroke="#9ba8b8"/><path d="M15 28L100 4L185 28L185 60L100 88L15 60Z" fill="url(#top)" stroke="#c8ba9c" stroke-width="2"/><path d="M34 25L34 65M165 25V65" stroke="#c8b58c" stroke-width="3"/><path d="M49 28L100 13L151 28M49 67L100 81L151 67" fill="none" stroke="#a9b5c1"/><path d="M85 43L100 38L115 43M85 53L100 48L115 53" stroke="#8db5bf" stroke-width="2" fill="none"/></svg>'''.replace('</svg>',''))
print('Exported nine modular architecture assets with bevels, risers and shadows.')
